/**
 * Value Reference system — the foundation of the SDK's type-safe data flow.
 *
 * A Ref<T> is a *description* of a runtime value, not the value itself.
 * It carries enough metadata to serialize into the Elementum API's
 * ValueReferenceInput format (trigger refs, action refs, forEach refs,
 * static values, and template strings).
 *
 * TypeScript sees the phantom T so autocomplete and type checking work;
 * the runtime Proxy layer (see context.ts) constructs these automatically
 * when agent code accesses ctx.trigger.* or ctx.actions.*.
 */
import { EdkValidationError } from "../../../elementum-entity-client/errors.js";
// ---------------------------------------------------------------------------
// Branded Ref<T> type
// ---------------------------------------------------------------------------
const REF_BRAND = Symbol("Ref");
export function createRef(data) {
    return {
        [REF_BRAND]: true,
        __type: undefined,
        __calculationType: undefined,
        __data: data,
    };
}
export function isRef(value) {
    return (typeof value === "object" &&
        value !== null &&
        REF_BRAND in value &&
        value[REF_BRAND] === true);
}
// ---------------------------------------------------------------------------
// Convenience helpers for explicit ref construction
// ---------------------------------------------------------------------------
/** Create a static-value reference. */
export function val(value) {
    return createRef({ kind: "static", value });
}
/**
 * Create a template-string reference from interleaved strings and refs.
 *
 * Rejects any literal string fragment that ends in `$` when immediately
 * followed by a `Ref<...>` — the UI can't render that pattern (see
 * plans/edk-shortcomings.md #27). Dynamic/computed string fragments that
 * the type system can't inspect are caught at serialize time by an
 * escape-character insertion pass.
 */
export function template(...parts) {
    const data = parts.map((p) => isRef(p) ? p.__data : String(p));
    return createRef({ kind: "template", parts: data });
}
/**
 * Reference a named secret by id. The resolver at execution time fetches
 * the plaintext from the Elementum secret vault. EDK never sees the
 * plaintext.
 *
 * @example
 * ```ts
 * apiRequest({
 *   url: "https://api.example.com",
 *   method: "GET",
 *   authorization: { type: "bearer", token: secret("payments-provider-token") },
 * })
 * ```
 */
export function secret(secretId) {
    if (!secretId || typeof secretId !== "string") {
        throw new EdkValidationError("secret() requires a non-empty string secretId.");
    }
    return createRef({ kind: "secret", secretId });
}
/**
 * Marker prefix embedded in a trigger ref's `record.<field>` name when the
 * field couldn't be resolved. `unresolvedField` writes it;
 * `src/deploy/plan/resolve-record-refs.ts` strips it back off and passes the
 * raw id straight through to the wire, unchecked against the field catalog —
 * keep both sides in sync.
 */
export const UNRESOLVED_FIELD_MARKER = "__edkUnresolvedField::";
/**
 * Escape hatch for a `ctx.trigger.record.<field>` reference the pull-time
 * deserializer couldn't resolve to any field in the owning app's catalog —
 * the wire field id/clientHandle isn't present there (deleted, orphaned, or
 * otherwise never captured). `RecordShape<A>` is closed over the app's known
 * fields, so a raw/unknown id has no normal spelling through
 * `ctx.trigger.record`; this bypasses that typed proxy entirely.
 *
 * `rawFieldId` round-trips straight through to the platform unchanged on
 * deploy — EDK never validates it against the field catalog, so it also never
 * blocks the plan.
 */
export function unresolvedField(rawFieldId) {
    if (!rawFieldId || typeof rawFieldId !== "string") {
        throw new EdkValidationError("unresolvedField() requires a non-empty string rawFieldId.");
    }
    return createRef({ kind: "trigger", name: `record.${UNRESOLVED_FIELD_MARKER}${rawFieldId}` });
}
/**
 * Unwrap ValueOrRef to its underlying RefData.
 * Literal values become static refs.
 */
export function toRefData(v) {
    if (isRef(v))
        return v.__data;
    return { kind: "static", value: v };
}
/**
 * Normalize a string-typed task field so the Mobius UI's templating layer
 * can render it. The platform expects these fields as a `templateReference`;
 * a bare trigger/task/forEach ref serializes to a single-kind ref and the
 * UI either renders empty (postComment.contents) or throws
 * `e.matchAll is not a function` (sendEmail.messageBody) when it tries to
 * expand placeholders.
 *
 * Plain strings and explicit `template(...)` values pass through unchanged.
 * Any other ref kind is wrapped in a one-parameter template.
 */
export function ensureTemplate(value) {
    if (!isRef(value))
        return value;
    if (value.__data.kind === "template")
        return value;
    return template(value);
}
